# =========== FINGERPRINT ===============
import ssl

def create_chrome_ssl_context():
    """Chrome-like TLS 1.2/1.3 cipher suite order"""
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE

    CHROME_CIPHERS = (
        "TLS_AES_128_GCM_SHA256:"
        "TLS_AES_256_GCM_SHA384:"
        "TLS_CHACHA20_POLY1305_SHA256:"
        "ECDHE-ECDSA-AES128-GCM-SHA256:"
        "ECDHE-RSA-AES128-GCM-SHA256:"
        "ECDHE-ECDSA-AES256-GCM-SHA384:"
        "ECDHE-RSA-AES256-GCM-SHA384:"
        "ECDHE-ECDSA-CHACHA20-POLY1305:"
        "ECDHE-RSA-CHACHA20-POLY1305:"
        "ECDHE-RSA-AES128-SHA:"
        "ECDHE-RSA-AES256-SHA"
    )
    try:
        ctx.set_ciphers(CHROME_CIPHERS)
    except Exception:
        pass
    return ctx

CHROME_SSL_CTX = create_chrome_ssl_context()

# =========== curl_cffi BROWSER IMPERSONATION TARGETS ===============
# Real Chrome/Edge TLS fingerprints — curl_cffi impersonates these at the
# TLS ClientHello + HTTP/2 SETTINGS level, making requests indistinguishable
# from genuine browser traffic to Cloudflare / Akamai / PerimeterX / Shopify.
_CFFI_IMPERSONATE_TARGETS = [
    "chrome120", "chrome123", "chrome124", "chrome131",
]

def _pick_impersonate():
    """Pick a random browser impersonation target for curl_cffi."""
    return random.choice(_CFFI_IMPERSONATE_TARGETS)


class SessionFingerprint:
    """
    Generates a NEW, 100% internally-consistent browser profile per session.
    UA, sec-ch-ua, sec-ch-ua-platform, and Accept-Language all correlate properly.
    """
    _RELEASES = {
        128: ("6613", ["84", "113", "137", "178"]),
        129: ("6668", ["58", "70", "89", "100"]),
        130: ("6723", ["44", "58", "69", "91"]),
        131: ("6778", ["69", "85", "108", "139", "204"]),
        132: ("6834", ["33", "57", "83", "110"]),
        133: ("6943", ["33", "53", "98", "126"]),
    }

    _PLATFORMS = [
        {"ua_os": "Windows NT 10.0; Win64; x64",        "platform": '"Windows"'},
        {"ua_os": "Windows NT 10.0; Win64; x64",        "platform": '"Windows"'},
        {"ua_os": "Macintosh; Intel Mac OS X 10_15_7",  "platform": '"macOS"'},
        {"ua_os": "Macintosh; Intel Mac OS X 14_7_1",   "platform": '"macOS"'},
        {"ua_os": "X11; Linux x86_64",                  "platform": '"Linux"'},
    ]

    _NOT_A_BRAND = [
        ('"Not_A Brand"', "8"),
        ('"Not-A.Brand"', "24"),
        ('"Not/A)Brand"', "8"),
        ('"Not A(Brand"', "99"),
        ('"Not?A_Brand"', "24"),
    ]

    _LANGUAGES = [
        "en-US,en;q=0.9",
        "en-US,en;q=0.9,es;q=0.8",
        "en-GB,en;q=0.9,en-US;q=0.8",
        "en-US,en;q=0.9,fr;q=0.8",
        "en,en-US;q=0.9",
        "en-US,en;q=0.9,de;q=0.8",
    ]

    @classmethod
    def create_new(cls):
        browser_type = random.choices(["chrome", "edge"], weights=[80, 20])[0]
        major = random.choice(list(cls._RELEASES.keys()))
        build_base, patches = cls._RELEASES[major]
        patch = random.choice(patches)
        full_ver = f"{major}.0.{build_base}.{patch}"

        plt = random.choice(cls._PLATFORMS)
        lang = random.choice(cls._LANGUAGES)

        if browser_type == "chrome":
            ua = (
                f"Mozilla/5.0 ({plt['ua_os']}) AppleWebKit/537.36 "
                f"(KHTML, like Gecko) Chrome/{full_ver} Safari/537.36"
            )
            browser_token = f'"Google Chrome";v="{major}"'
        else:
            edge_patch = random.choice(patches)
            ua = (
                f"Mozilla/5.0 ({plt['ua_os']}) AppleWebKit/537.36 "
                f"(KHTML, like Gecko) Chrome/{full_ver} Safari/537.36 "
                f"Edg/{major}.0.{build_base}.{edge_patch}"
            )
            browser_token = f'"Microsoft Edge";v="{major}"'

        brand_name, brand_ver = random.choice(cls._NOT_A_BRAND)
        tokens = [
            f'"Chromium";v="{major}"',
            f'{brand_name};v="{brand_ver}"',
            browser_token,
        ]
        random.shuffle(tokens)

        return {
            "ua": ua,
            "sec_ch_ua": ", ".join(tokens),
            "platform": plt["platform"],
            "mobile": "?0",
            "lang": lang,
        }


# =========== SITES DATABASE (sites.json) ===============
SITES_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sites.json")

_sites_pool = []
_site_rr_index = 0
_sites_lock = threading.Lock()

def load_sites_pool(file_path=SITES_FILE):
    """
    Load sites and their pre-scraped variant IDs from sites.json.
    Format: {"sites": [{"site": "https://...", "variants": ["123", "456"]}, ...]}
    Each site maintains its own rotating variant pointer.
    """
    global _sites_pool
    if not os.path.exists(file_path):
        logger.warning(f"[load_sites_pool] Warning: {file_path} not found.")
        return 0
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        pool = []
        for item in data.get("sites", []):
            s = item.get("site", "").strip().rstrip("/").rstrip("\\")
            v_list = [str(v).strip() for v in item.get("variants", []) if str(v).strip()]
            if s and v_list:
                pool.append({
                    "site": s,
                    "variants": v_list,
                    "var_index": random.randint(0, len(v_list) - 1)
                })
        random.shuffle(pool)
        _sites_pool = pool
        return len(pool)
    except Exception as e:
        logger.error(f"[load_sites_pool] Error reading {file_path}: {e}")
        return 0

_total_loaded_sites = load_sites_pool()

def pick_site_and_variant(preferred_site=None, preferred_variant=None):
    """
    Pick site and variant with guaranteed rotation:
    - Har request me SITE rotate hoti hai round-robin across all loaded sites.
    - Us site ka VARIANT bhi ALWAYS rotate hota hai (never the same variant repeatedly).
    - Agar caller preferred_site pass kare, toh usi site ke variants rotate honge.
    """
    global _site_rr_index

    with _sites_lock:
        if not _sites_pool:
            return preferred_site, preferred_variant

        if preferred_site:
            s_clean = preferred_site.strip().rstrip("/").rstrip("\\")
            if preferred_variant:
                return s_clean, str(preferred_variant).strip()
            # Find site in pool to rotate through its variants
            for item in _sites_pool:
                if item["site"] == s_clean and item["variants"]:
                    v = item["variants"][item["var_index"] % len(item["variants"])]
                    item["var_index"] += 1
                    return s_clean, v
            return s_clean, None

        # Rotate site sequentially
        item = _sites_pool[_site_rr_index % len(_sites_pool)]
        _site_rr_index += 1

        # Rotate variant for this site sequentially
        if item["variants"]:
            v = item["variants"][item["var_index"] % len(item["variants"])]
            item["var_index"] += 1
        else:
            v = None

        return item["site"], v

def get_fallback_variant_for_site(site_url, failed_vid=None):
    """
    If a variant failed cart/checkout, return an alternative variant for the same site or any site.
    Advances the variant pointer so it does not retry the same failed variant.
    """
    s_clean = site_url.strip().rstrip("/").rstrip("\\")
    with _sites_lock:
        for item in _sites_pool:
            if item["site"] == s_clean and item["variants"]:
                alternatives = [v for v in item["variants"] if v != str(failed_vid)]
                if alternatives:
                    item["var_index"] += 1
                    return alternatives[item["var_index"] % len(alternatives)]
        # Global fallback variant from pool
        if _sites_pool:
            random_site = random.choice(_sites_pool)
            if random_site["variants"]:
                random_site["var_index"] += 1
                return random_site["variants"][random_site["var_index"] % len(random_site["variants"])]
    return None


