ADDRESSES_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "address.json")

_addresses_by_country = {}
_all_addresses = []

def load_addresses(file_path=ADDRESSES_FILE):
    """
    Load addresses from address.json into memory grouped by country_code.
    Format: {"US": [{firstName, lastName, address1, address2, city, countryCode, zoneCode, postalCode, phone, email_domain}, ...], ...}
    Falls back to demo.txt or addresses.txt if JSON is missing.
    """
    global _addresses_by_country, _all_addresses
    by_country = {}
    all_list = []

    if not os.path.exists(file_path):
        # Fallback to demo.txt or addresses.txt
        for fb_name in ("demo.txt", "addresses.txt"):
            fb_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), fb_name)
            if os.path.exists(fb_path):
                file_path = fb_path
                break
        else:
            logger.warning(f"[load_addresses] Warning: {file_path} not found.")
            return 0

    if file_path.endswith('.json'):
        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            for c_code, addr_list in data.items():
                c_upper = c_code.upper()
                if c_upper not in by_country:
                    by_country[c_upper] = []
                for entry in addr_list:
                    by_country[c_upper].append(entry)
                    all_list.append(entry)
            _addresses_by_country = by_country
            _all_addresses = all_list
            return len(all_list)
        except Exception as e:
            logger.error(f"[load_addresses] Error reading JSON {file_path}: {e}")
            return 0
    else:
        # Fallback text format loader
        with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                parts = [p.strip() for p in line.split("|")]
                if len(parts) != 10:
                    continue
                entry = {
                    "firstName": parts[0].capitalize(),
                    "lastName": parts[1].capitalize(),
                    "address1": parts[2],
                    "address2": parts[3],
                    "city": parts[4],
                    "countryCode": parts[5].upper(),
                    "zoneCode": parts[6].upper(),
                    "postalCode": parts[7],
                    "phone": parts[8],
                    "email_domain": parts[9].lower(),
                }
                c_code = entry["countryCode"]
                if c_code not in by_country:
                    by_country[c_code] = []
                by_country[c_code].append(entry)
                all_list.append(entry)

        _addresses_by_country = by_country
        _all_addresses = all_list
        return len(all_list)

