def pick_addr(url, cc=None, rc=None):
    """
    Pick a realistic address matching the store's country/region from address.json.
    Supports all countries, currencies, and top-level domains.
    """
    dom = urlparse(url).netloc
    tld = dom.split('.')[-1].upper()

    target_country = None
    if cc and cc.upper() in C2C:
        target_country = C2C[cc.upper()]
    elif tld in TLD2C:
        target_country = TLD2C[tld]
    elif tld in _addresses_by_country:
        target_country = tld
    elif rc and rc.upper() in _addresses_by_country:
        target_country = rc.upper()

    ZERO_TAX_STATES = {'DE', 'MT', 'NH', 'OR', 'AK'}
    if target_country and target_country in _addresses_by_country and _addresses_by_country[target_country]:
        pool = _addresses_by_country[target_country]
        if target_country == 'US':
            low_tax = [a for a in pool if a.get('zoneCode') in ZERO_TAX_STATES]
            if low_tax:
                return random.choice(low_tax)
        return random.choice(pool)

    # Default fallback: US (prioritize 0% tax states)
    if "US" in _addresses_by_country and _addresses_by_country["US"]:
        us_pool = _addresses_by_country["US"]
        low_tax = [a for a in us_pool if a.get('zoneCode') in ZERO_TAX_STATES]
        if low_tax:
            return random.choice(low_tax)
        return random.choice(us_pool)
    elif _all_addresses:
        return random.choice(_all_addresses)

    # Hard emergency fallback if address.json is completely missing (Delaware - 0% Tax)
    return {
        "firstName": "James", "lastName": "Anderson", "address1": "1000 N West St",
        "address2": "Suite 1200", "city": "Wilmington", "countryCode": "US", "zoneCode": "DE",
        "postalCode": "19801", "phone": "+13025550101", "email_domain": "gmail.com"
    }

def capture(data, first, last):
    try:
        start = data.index(first) + len(first)
        end = data.index(last, start)
        return data[start:end]
    except ValueError:
        return None

def extract_between(text, start, end):
    if not text or not start or not end:
        return None
    try:
        if start in text:
            parts = text.split(start, 1)
            if len(parts) > 1:
                if end in parts[1]:
                    result = parts[1].split(end, 1)[0]
                    return result if result else None
        return None
    except Exception:
        return None

