# =========== NETWORK UTILITIES ===============
def parse_proxy(proxy_str):
    """
    Parse proxy string into an aiohttp-compatible URL.
    Supports any host (alphanumeric, dots, hyphens, underscores, subdomains, IPs),
    passwords containing colons or symbols, and any of the following formats:
      - host:port:user:pass
      - host:port
      - user:pass@host:port
      - user:pass:host:port
      - http(s):// / socks5:// prefixes
    """
    if not proxy_str or not isinstance(proxy_str, str):
        return None

    raw = proxy_str.strip().strip('"\'')
    if not raw:
        return None

    s = raw
    # Strip protocol prefix if present
    for prefix in ('http://', 'https://', 'socks5://', 'socks4://'):
        if s.lower().startswith(prefix):
            s = s[len(prefix):]
            break

    # Format 1: user:pass@host:port (or user@email:pass@host:port)
    if '@' in s:
        try:
            auth, server = s.rsplit('@', 1)
            if ':' in auth and ':' in server:
                user, password = auth.split(':', 1)
                host, port = server.rsplit(':', 1)
                host = host.strip()
                port = port.strip()
                if port.isdigit() and 1 <= int(port) <= 65535 and host:
                    u_enc = urllib.parse.quote(user.strip(), safe='')
                    p_enc = urllib.parse.quote(password.strip(), safe='')
                    return f"http://{u_enc}:{p_enc}@{host}:{port}"
        except Exception as e:
            logger.warning(f"[parse_proxy] Error parsing @ format proxy: {e}")

    # Format 2 & 3: Colon-separated parts
    parts = s.split(':')
    if len(parts) == 2:
        host = parts[0].strip()
        port = parts[1].strip()
        if port.isdigit() and 1 <= int(port) <= 65535 and host:
            return f"http://{host}:{port}"

    elif len(parts) >= 4:
        # Standard: host:port:user:pass (port is 2nd token)
        # Handles any host (symbols, letters, digits) and passwords containing colons
        if parts[1].strip().isdigit() and 1 <= int(parts[1].strip()) <= 65535:
            host = parts[0].strip()
            port = parts[1].strip()
            user = parts[2].strip()
            password = ':'.join(parts[3:]).strip()
            if host:
                u_enc = urllib.parse.quote(user, safe='')
                p_enc = urllib.parse.quote(password, safe='')
                return f"http://{u_enc}:{p_enc}@{host}:{port}"

        # Alternative: user:pass:host:port (port is last token)
        elif parts[-1].strip().isdigit() and 1 <= int(parts[-1].strip()) <= 65535:
            host = parts[-2].strip()
            port = parts[-1].strip()
            user = parts[0].strip()
            password = ':'.join(parts[1:-2]).strip()
            if host:
                u_enc = urllib.parse.quote(user, safe='')
                p_enc = urllib.parse.quote(password, safe='')
                return f"http://{u_enc}:{p_enc}@{host}:{port}"

    logger.warning(f"[parse_proxy] Invalid proxy format: {raw}")
    return None

def is_captcha_required(response_text):
    if not response_text:
        return False

    indicators = [
        'CAPTCHA_REQUIRED',
        '"code":"CAPTCHA_REQUIRED"',
        "'code':'CAPTCHA_REQUIRED'",
        '"message":"CAPTCHA_REQUIRED"',
        'captcha required',
        'CAPTCHA CHALLENGE',
        'hcaptcha',
        'h-captcha'
    ]

    text_upper = response_text.upper()
    for indicator in indicators:
        if indicator.upper() in text_upper:
            return True
    return False

async def make_graphql_request_with_captcha_handling(
    session, graphql_url, params, headers, json_data,
    checkout_url, max_retries=1, solve_captcha=True, proxy=None
):
    response = None
    response_text = ""

    for attempt in range(max_retries + 1):
        try:
            response = await session.post(
                graphql_url, params=params, headers=headers, json=json_data,
                timeout=TIMEOUT_GRAPHQL, proxy=proxy
            )
            response_text = response.text
            return response, response_text, False

        except asyncio.TimeoutError:
            if attempt == max_retries:
                return None, "Request timed out", False
            await asyncio.sleep(0.5)
        except Exception as e:
            err_str = str(e).lower()
            if attempt == max_retries:
                if 'proxy' in err_str or 'connect' in err_str or '407' in err_str:
                    return None, "Proxy Error: Authentication failed or proxy rejected", False
                return None, f"Network error: {str(e)}", False
            await asyncio.sleep(0.3)

    return response, response_text, False

# =========== PRODUCT FETCHER ===============
async def fetch_products(domain, proxy_str=None):
    last_err = "Unknown error"
    if not domain.startswith('http'):
        domain = "https://" + domain
    proxy = parse_proxy(proxy_str) if proxy_str else None

    # ✅ Proxy validation
    if proxy_str and not proxy:
        logger.error(f"[fetch_products] Invalid proxy format: {proxy_str[:50]}")
        return False, f"Invalid proxy format: {proxy_str[:30]}"

    fp = SessionFingerprint.create_new()
    fetch_headers = {
        'Accept': 'application/json, text/javascript, */*; q=0.01',
        'Accept-Language': fp['lang'],
        'sec-fetch-dest': 'empty',
        'sec-fetch-mode': 'cors',
        'sec-fetch-site': 'same-origin',
        'Referer': domain
    }

    for attempt in range(3):
        try:
            async with CffiAsyncSession(impersonate=_pick_impersonate(), timeout=TIMEOUT_PRODUCT_FETCH, verify=False) as session:
                resp = await session.get(f"{domain}/products.json", headers=fetch_headers, proxy=proxy)

                if resp.status_code != 200:
                    last_err = f"<b>Site Error! Status: {resp.status_code}</b>"
                    if resp.status_code == 429:
                        logger.warning(f"[fetch_products] HTTP 429 Rate limited on {domain} | Proxy: {proxy_str[:30] if proxy_str else 'Direct'} | Backing off 1.5s...")
                        await asyncio.sleep(1.5)
                    else:
                        await asyncio.sleep(0.3)
                    continue

                text = resp.text
                if "shopify" not in text.lower():
                    return False, "<b>Not Shopify!</b>"

                result = json.loads(text).get('products', [])
                if not result:
                    return False, "<b>No Products!</b>"

            min_price = float('inf')
            min_product = None

            for product in result:
                if not product.get('variants'):
                    continue
                for variant in product['variants']:
                    if not variant.get('available', True):
                        continue
                    try:
                        price = float(str(variant.get('price', '0')).replace(',', ''))
                        if price <= 0.0:
                            continue  # Gateways require positive amount > 0.00
                        if price < min_price:
                            min_price = price
                            min_product = {
                                'site': domain,
                                'price': f"{price:.2f}",
                                'variant_id': str(variant['id']),
                                'link': f"{domain}/products/{product['handle']}"
                            }
                    except (ValueError, TypeError, AttributeError):
                        continue

            if min_product and min_product.get('variant_id'):
                return min_product
            else:
                return False, "<b>No Valid Products</b>"

        except Exception as e:
            err = str(e).lower()
            if 'timeout' in err: last_err = "Proxy Error: Connection timed out"
            elif 'auth' in err or '407' in err: last_err = "Proxy Error: Authentication failed"
            else: last_err = f"Proxy Error: Could not connect ({str(e)})"

        await asyncio.sleep(0.2)

    return False, last_err

# =========== RESPONSE PARSER ===============
def extract_clean_response(message):
    if not message:
        return "UNKNOWN_ERROR"

    message = str(message)

    patterns = [
        r'(PAYMENTS_[A-Z_]+)',
        r'(CARD_[A-Z_]+)',
        r'([A-Z]+_[A-Z]+_[A-Z_]+)',
        r'([A-Z]+_[A-Z_]+)',
        r'code["\']?\s*[:=]\s*["\']?([^"\',]+)["\']?',
        r'{"code":"([^"]+)"',
        r"'code':'([^']+)'"
    ]

    for pattern in patterns:
        matches = re.findall(pattern, message, re.IGNORECASE)
        for match in matches:
            if isinstance(match, tuple):
                match = match[0]
            if match and "_" in match and len(match) < 50:
                match = match.strip("{}:'\" ")
                return match

    words = message.split()
    if words:
        first_word = words[0]
        if "_" in first_word and first_word.isupper():
            return first_word

    return message[:50]

