@app.post('/reload')
@app.get('/reload')
def reload_data():
    """Hot-reload address.json and sites.json without server restart."""
    sites_cnt = load_sites_pool()
    addr_cnt = load_addresses()
    return {
        "status": "reloaded",
        "sites_loaded": sites_cnt,
        "addresses_loaded": addr_cnt,
        "countries_covered": len(_addresses_by_country)
    }


